#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
BED BOUNCE — Python (pygame) version of the Bed Bounce web game.
Polished UI edition.

Stick figures with real photo faces fall from the sky.
Drag the bed to catch them — every catch is a bounce + 1 point.
Miss one and it's SPLAT!

Web version : https://xdotdex.github.io/Fuckgames/
GitHub      : https://github.com/XDOTDEX

Run:
    pip install pygame
    python bed_bounce.py

Controls:
    Mouse drag / arrow keys   move the bed
    SPACE                      pause / resume
    ENTER                      start / play again
    M                          sound on/off
    Drop an image file onto the window (or put myface.png next to
    this script) to use your own photo as the falling face.
"""

import base64
import io
import math
import os
import random
import sys

import pygame

# ----------------------------------------------------------------------------
# Embedded assets (same faces + sounds as the web version)
# ----------------------------------------------------------------------------
_BOUNCE_B64 = [
    "",
    "",
    "",
]
_SPLAT_B64 = ""
_GAMEOVER_B64 = ""
_SLEEPER_B64 = ""
_FALLER_B64 = [
    "",
    "",
]

QUOTE_TEXT = "No awakening here. Only sleep that never ends, among dead stars"
GITHUB_CREDIT = "github.com/XDOTDEX"

# Palette — warm cream room, deep green blanket, gold accents
SKY_TOP = (253, 249, 240)
SKY_BOT = (243, 234, 214)
FLOOR_TOP = (232, 220, 194)
FLOOR_BOT = (214, 198, 164)
FLOOR_LINE = (196, 180, 142)
INK = (24, 24, 24)
TEXT_DARK = (43, 43, 43)
TEXT_MID = (111, 106, 94)
TEXT_SOFT = (154, 149, 138)
MATRESS_TOP = (243, 239, 228)
MATRESS_BOT = (224, 218, 200)
FRAME = (104, 104, 104)
HEAD_TOP = (164, 110, 60)
HEAD_BOT = (128, 82, 44)
LEG_COL = (58, 44, 32)
BLANKET_TOP = (43, 107, 79)
BLANKET_BOT = (24, 66, 48)
PILLOW = (255, 255, 255)
GOLD = (232, 168, 18)
GOLD_DARK = (190, 134, 10)
QUOTE_COL = (133, 118, 88)
CREDIT_COL = (110, 100, 80)
BTN_DARK = (43, 43, 43)
BTN_DARK_HOV = (66, 66, 66)
CARD = (255, 253, 248)

OVER_MSGS = [
    "He missed the bed…",
    "So close! The floor is not soft.",
    "The sleeper didn't even wake up.",
    "Gravity wins this round.",
    "Ouch. Right on the floorboards.",
]


def _img_from_b64(b64):
    try:
        return pygame.image.load(io.BytesIO(base64.b64decode(b64))).convert_alpha()
    except Exception:
        return None


def _snd_from_b64(b64):
    try:
        return pygame.mixer.Sound(io.BytesIO(base64.b64decode(b64)))
    except Exception:
        return None


def vgrad(w, h, top, bot):
    """Vertical gradient surface."""
    surf = pygame.Surface((max(1, int(w)), max(1, int(h))))
    for i in range(max(1, int(h))):
        t = i / max(1, int(h) - 1)
        col = tuple(int(top[c] + (bot[c] - top[c]) * t) for c in range(3))
        pygame.draw.line(surf, col, (0, i), (int(w), i))
    return surf


def shadow_rect(surf, rect, radius=18, alpha=46, grow=6, yoff=5):
    sh = pygame.Surface((rect.w + grow * 2, rect.h + grow * 2), pygame.SRCALPHA)
    pygame.draw.rect(sh, (60, 45, 20, alpha), sh.get_rect(), border_radius=radius + grow)
    surf.blit(sh, (rect.x - grow, rect.y - grow + yoff))


# ----------------------------------------------------------------------------
# Game
# ----------------------------------------------------------------------------
class BedBounce:
    def __init__(self):
        pygame.init()
        pygame.display.set_caption("Bed Bounce — by XDOTDEX")
        self.W, self.H = 480, 800
        self.screen = pygame.display.set_mode((self.W, self.H), pygame.RESIZABLE)
        self.clock = pygame.time.Clock()
        self.mouse = (0, 0)

        self.f_score = pygame.font.SysFont("arial", 46, bold=True)
        self.f_best = pygame.font.SysFont("arial", 12, bold=True)
        self.f_quote = pygame.font.SysFont("arial", 19, bold=True, italic=True)
        self.f_credit = pygame.font.SysFont("arial", 12, bold=True)
        self.f_title = pygame.font.SysFont("arial", 36, bold=True)
        self.f_body = pygame.font.SysFont("arial", 15)
        self.f_body_b = pygame.font.SysFont("arial", 15, bold=True)
        self.f_big = pygame.font.SysFont("arial", 68, bold=True)
        self.f_btn = pygame.font.SysFont("arial", 17, bold=True)
        self.f_small = pygame.font.SysFont("arial", 12)

        self.sleeper_img = _img_from_b64(_SLEEPER_B64)
        self.faller_imgs = [i for i in (_img_from_b64(b) for b in _FALLER_B64) if i]
        self.custom_face = self._load_custom_face()

        self.sounds_ready = False
        self.snd_bounce, self.snd_splat, self.snd_over = [], None, None
        try:
            pygame.mixer.init()
            self.snd_bounce = [s for s in (_snd_from_b64(b) for b in _BOUNCE_B64) if s]
            self.snd_splat = _snd_from_b64(_SPLAT_B64)
            self.snd_over = _snd_from_b64(_GAMEOVER_B64)
            self.sounds_ready = bool(self.snd_bounce or self.snd_splat or self.snd_over)
        except Exception:
            self.sounds_ready = False
        self.sound_on = True

        self._face_cache = {}
        self._bg_cache = None
        self.best = self._load_best()

        self.state = "menu"  # menu | playing | paused | over
        self.score = 0
        self.frame = 0
        self.shake = 0.0
        self.flash_red = 0.0
        self.new_best = False
        self.over_at = 0
        self.state_at = pygame.time.get_ticks()
        self.over_msg = ""
        self.hint_until = 0

        self.bed_x = self.W / 2
        self.bed_target = self.W / 2
        self.bed_w = 280
        self.bed_top = self.H - 92
        self.squash = 0.0
        self.dragging = False
        self.drag_off = 0.0

        self.faller = None
        self.flyers = []
        self.particles = []
        self.splat = None
        self.timers = []
        self.btns = {}  # name -> rect (filled each render)
        self.layout()

    # ---------- files ----------
    def _dir(self):
        return os.path.dirname(os.path.abspath(__file__))

    def _load_best(self):
        try:
            with open(os.path.join(self._dir(), "bed_bounce_best.txt")) as fh:
                return int(fh.read().strip() or 0)
        except Exception:
            return 0

    def _save_best(self):
        try:
            with open(os.path.join(self._dir(), "bed_bounce_best.txt"), "w") as fh:
                fh.write(str(self.best))
        except Exception:
            pass

    def _load_custom_face(self):
        p = os.path.join(self._dir(), "myface.png")
        if os.path.exists(p):
            try:
                return pygame.image.load(p).convert_alpha()
            except Exception:
                return None
        return None

    # ---------- helpers ----------
    def layout(self):
        self.bed_w = max(210, min(self.W * 0.62, 330))
        self.bed_top = self.H - 92
        half = self.bed_w / 2
        self.bed_x = max(half, min(self.W - half, self.bed_x))
        self.bed_target = max(half, min(self.W - half, self.bed_target))
        self._bg_cache = None

    @property
    def floor_y(self):
        return self.H - 46

    def play(self, snd):
        if self.sound_on and self.sounds_ready and snd:
            try:
                snd.play()
            except Exception:
                pass

    def after(self, ms, fn):
        self.timers.append((pygame.time.get_ticks() + ms, fn))

    def set_state(self, st):
        self.state = st
        self.state_at = pygame.time.get_ticks()

    def circle_face(self, img, r):
        key = (id(img), r)
        if key in self._face_cache:
            return self._face_cache[key]
        d = r * 2
        surf = pygame.Surface((d, d), pygame.SRCALPHA)
        scaled = pygame.transform.smoothscale(img, (d, d))
        mask = pygame.Surface((d, d), pygame.SRCALPHA)
        pygame.draw.circle(mask, (255, 255, 255, 255), (r, r), r)
        surf.blit(scaled, (0, 0))
        surf.blit(mask, (0, 0), special_flags=pygame.BLEND_RGBA_MIN)
        self._face_cache[key] = surf
        return surf

    def draw_face(self, x, y, r, img, rot=0.0, mood=0, shadow=True):
        if shadow:
            sh = pygame.Surface((r * 2 + 8, r * 2 + 8), pygame.SRCALPHA)
            pygame.draw.circle(sh, (70, 55, 25, 60), (r + 4, r + 4), r)
            self.screen.blit(sh, (x - r - 4, y - r - 1))
        im = self.custom_face or img
        if im is not None:
            face = self.circle_face(im, r)
            if rot:
                face = pygame.transform.rotate(face, -math.degrees(rot))
            rect = face.get_rect(center=(int(x), int(y)))
            self.screen.blit(face, rect)
            pygame.draw.circle(self.screen, (30, 30, 30), (int(x), int(y)), r, 2)
        else:
            pygame.draw.circle(self.screen, (255, 217, 77), (int(x), int(y)), r)
            pygame.draw.circle(self.screen, (30, 30, 30), (int(x), int(y)), r, 2)
            ex, ey = max(3, r // 4), max(3, r // 5)
            if mood == 1:
                pygame.draw.arc(self.screen, INK, (x - ex - 4, y - ey - 3, 8, 6), math.pi, 2 * math.pi, 2)
                pygame.draw.arc(self.screen, INK, (x + ex - 4, y - ey - 3, 8, 6), math.pi, 2 * math.pi, 2)
                pygame.draw.circle(self.screen, INK, (int(x), int(y + r // 3)), max(2, r // 7))
            else:
                pygame.draw.circle(self.screen, INK, (int(x - ex), int(y - ey)), max(2, r // 8))
                pygame.draw.circle(self.screen, INK, (int(x + ex), int(y - ey)), max(2, r // 8))
                pygame.draw.arc(self.screen, INK, (x - r // 3, y + r // 6, 2 * (r // 3), r // 2), math.pi * 1.15, math.pi * 1.85, 2)

    def text(self, surf_text, font, col, center=None, pos=None, alpha=None, shadow=False):
        t = font.render(surf_text, True, col)
        if shadow:
            sh = font.render(surf_text, True, (255, 255, 255))
            sh.set_alpha(130)
            r = sh.get_rect(center=center) if center else sh.get_rect(topleft=pos)
            self.screen.blit(sh, (r.x, r.y + 2))
        if alpha is not None:
            t.set_alpha(alpha)
        r = t.get_rect(center=center) if center else t.get_rect(topleft=pos)
        self.screen.blit(t, r)
        return r

    # ---------- scene drawing ----------
    def draw_background(self):
        if self._bg_cache is None or self._bg_cache.get_size() != (self.W, self.H):
            bg = vgrad(self.W, self.H, SKY_TOP, SKY_BOT)
            # floor zone
            fy = self.floor_y
            fl = vgrad(self.W, self.H - fy, FLOOR_TOP, FLOOR_BOT)
            bg.blit(fl, (0, fy))
            pygame.draw.rect(bg, FLOOR_LINE, (0, fy, self.W, 3))
            for ly in range(fy + 16, self.H, 18):
                pygame.draw.line(bg, (198, 182, 144), (0, ly), (self.W, ly), 1)
            self._bg_cache = bg
        self.screen.blit(self._bg_cache, (0, 0))
        # soft drifting bokeh dots
        now = pygame.time.get_ticks() / 1000.0
        for i, (bx, by, br, sp) in enumerate([(0.12, 0.30, 26, 0.011), (0.85, 0.22, 18, 0.017),
                                              (0.68, 0.52, 12, 0.023), (0.25, 0.62, 14, 0.014),
                                              (0.92, 0.58, 22, 0.009)]):
            x = (bx + math.sin(now * sp * 6 + i * 2.1) * 0.012) * self.W
            y = (by + math.cos(now * sp * 5 + i * 1.7) * 0.010) * self.H
            dot = pygame.Surface((br * 2, br * 2), pygame.SRCALPHA)
            pygame.draw.circle(dot, (255, 252, 240, 90), (br, br), br)
            self.screen.blit(dot, (x - br, y - br))
        if self.flash_red > 0:
            ov = pygame.Surface((self.W, self.H), pygame.SRCALPHA)
            ov.fill((220, 60, 40, int(self.flash_red * 0.13 * 255)))
            self.screen.blit(ov, (0, 0))

    def draw_bed(self):
        s = self.screen
        w = self.bed_w
        left = self.bed_x - w / 2
        top = self.bed_top
        mh = 30 + self.squash * 10
        # ground shadow
        sh = pygame.Surface((int(w + 30), 26), pygame.SRCALPHA)
        pygame.draw.ellipse(sh, (80, 62, 30, 70), sh.get_rect())
        s.blit(sh, (left - 15, top + mh + 22))
        # legs
        pygame.draw.rect(s, LEG_COL, (left + 12, top + mh + 14, 10, 18), border_radius=3)
        pygame.draw.rect(s, LEG_COL, (left + w - 22, top + mh + 14, 10, 18), border_radius=3)
        # headboard (gradient wood)
        hb = vgrad(32, mh + 38, HEAD_TOP, HEAD_BOT)
        s.blit(hb, (left - 7, top - 58))
        pygame.draw.rect(s, (90, 58, 28), (left - 7, top - 58, 32, mh + 38), 2, border_radius=7)
        pygame.draw.rect(s, (255, 255, 255), (left - 2, top - 52, 21, mh + 26), 1, border_radius=5)
        # frame
        pygame.draw.rect(s, FRAME, (left, top + mh - 2, w, 18), border_radius=4)
        pygame.draw.rect(s, (70, 70, 70), (left, top + mh - 2, w, 18), 1, border_radius=4)
        # mattress (gradient)
        mt = vgrad(w, mh, MATRESS_TOP, MATRESS_BOT)
        s.blit(mt, (left, top))
        pygame.draw.rect(s, (120, 112, 92), (left, top, w, mh), 2, border_radius=7)
        # blanket (gradient) + fold stripe
        bx = left + 58
        bw = w - 58 - 2
        bl = vgrad(bw, mh + 9, BLANKET_TOP, BLANKET_BOT)
        s.blit(bl, (bx, top + 3))
        pygame.draw.rect(s, (16, 46, 33), (bx, top + 3, bw, mh + 9), 1, border_radius=7)
        pygame.draw.rect(s, (255, 255, 255, 40)[:3], (bx + 4, top + 6, bw - 8, 3))
        # pillow with soft shadow
        psh = pygame.Surface((64, 32), pygame.SRCALPHA)
        pygame.draw.rect(psh, (80, 62, 30, 60), psh.get_rect(), border_radius=10)
        s.blit(psh, (left + 6, top - 8))
        pygame.draw.rect(s, PILLOW, (left + 8, top - 12, 56, 26), border_radius=10)
        pygame.draw.rect(s, (178, 170, 150), (left + 8, top - 12, 56, 26), 1, border_radius=10)
        # sleeper face
        self.draw_face(left + 36, top + 1, 19, self.sleeper_img, rot=-0.06, mood=1, shadow=False)
        # sleeper's stick legs
        lx, ly = left + w - 6, top + mh - 2
        for pts in [((lx - 16, ly - 4), (lx + 8, ly - 12), (lx + 16, ly - 10)),
                    ((lx - 14, ly + 2), (lx + 10, ly + 2), (lx + 18, ly + 5))]:
            pygame.draw.lines(s, INK, False, pts, 3)
            for px, py in pts[1:]:
                pygame.draw.circle(s, INK, (int(px), int(py)), 2)

    def draw_stick(self, f):
        s = self.screen
        t = pygame.time.get_ticks() / 90.0 + f["phase"] * 10
        flail = 1.0 if f["state"] == "falling" else 0.4
        a1 = math.sin(t) * 0.7 * flail
        a2 = math.cos(t * 1.13) * 0.7 * flail
        l1 = math.sin(t * 1.31) * 0.8 * flail
        l2 = math.cos(t * 0.91) * 0.8 * flail
        fx, fy = f["x"], f["y"]
        neck_y = fy + f["r"] * 0.85
        hip_y = neck_y + 26
        lw = 4
        limbs = [
            ((fx, neck_y), (fx, hip_y)),
            ((fx, neck_y + 5), (fx + math.cos(a1) * 24, neck_y + 5 + math.sin(a1) * 24)),
            ((fx, neck_y + 5), (fx - math.cos(a2) * 24, neck_y + 5 + math.sin(a2) * 24)),
            ((fx, hip_y), (fx + math.sin(l1) * 22, hip_y + 24)),
            ((fx, hip_y), (fx - math.sin(l2) * 22, hip_y + 24)),
        ]
        for p1, p2 in limbs:
            pygame.draw.line(s, INK, p1, p2, lw)
            pygame.draw.circle(s, INK, (int(p2[0]), int(p2[1])), 2)
        pygame.draw.circle(s, INK, (int(fx), int(hip_y)), 2)
        self.draw_face(fx, fy, f["r"], f["img"], rot=f["rot"])
        return hip_y + 24

    def draw_quote(self):
        cyc = (pygame.time.get_ticks() % 5000) / 5000.0
        wave = math.sin(cyc * 2 * math.pi - math.pi / 2) * 0.5 + 0.5
        alpha = int(255 * (0.38 + 0.57 * wave))
        y_off = -7 * wave
        words = QUOTE_TEXT.split()
        lines, cur = [], ""
        for wd in words:
            trial = (cur + " " + wd).strip()
            if self.f_quote.size(trial)[0] <= self.W * 0.84:
                cur = trial
            else:
                lines.append(cur)
                cur = wd
        if cur:
            lines.append(cur)
        y = self.H * 0.205 + y_off
        for ln in lines:
            self.text(ln, self.f_quote, QUOTE_COL, center=(self.W / 2, y), alpha=alpha, shadow=True)
            y += 30

    def draw_hud(self):
        self.text(str(self.score), self.f_score, TEXT_DARK, center=(self.W / 2, 34), shadow=True)
        # BEST pill
        label = "BEST  %d" % self.best
        tw = self.f_best.size(label)[0]
        pill = pygame.Rect(self.W / 2 - tw / 2 - 12, 56, tw + 24, 20)
        ps = pygame.Surface(pill.size, pygame.SRCALPHA)
        pygame.draw.rect(ps, (255, 255, 255, 150), ps.get_rect(), border_radius=10)
        self.screen.blit(ps, pill.topleft)
        pygame.draw.rect(self.screen, (210, 200, 170), pill, 1, border_radius=10)
        self.text(label, self.f_best, TEXT_MID, center=pill.center)

    def draw_corner_buttons(self):
        # left: sound toggle, right: pause — frosted rounded squares
        for name, x in (("sound", 10), ("pause", self.W - 48)):
            rect = pygame.Rect(x, 10, 38, 38)
            self.btns[name] = rect
            hov = rect.collidepoint(self.mouse)
            bs = pygame.Surface(rect.size, pygame.SRCALPHA)
            pygame.draw.rect(bs, (255, 255, 255, 205 if hov else 165), bs.get_rect(), border_radius=11)
            self.screen.blit(bs, rect.topleft)
            pygame.draw.rect(self.screen, (216, 205, 182), rect, 1, border_radius=11)
        # sound icon
        r = self.btns["sound"]
        cx, cy = r.centerx, r.centery
        pygame.draw.polygon(self.screen, TEXT_DARK, [(cx - 9, cy - 3), (cx - 4, cy - 3), (cx + 2, cy - 8),
                                                     (cx + 2, cy + 8), (cx - 4, cy + 3), (cx - 9, cy + 3)])
        if self.sound_on:
            pygame.draw.arc(self.screen, TEXT_DARK, (cx + 2, cy - 7, 9, 14), -1.1, 1.1, 2)
            pygame.draw.arc(self.screen, TEXT_DARK, (cx + 4, cy - 10, 12, 20), -1.1, 1.1, 2)
        else:
            pygame.draw.line(self.screen, (200, 60, 40), (cx + 4, cy - 6), (cx + 12, cy + 6), 2)
            pygame.draw.line(self.screen, (200, 60, 40), (cx + 12, cy - 6), (cx + 4, cy + 6), 2)
        # pause icon
        r = self.btns["pause"]
        cx, cy = r.centerx, r.centery
        if self.state == "paused":
            pygame.draw.polygon(self.screen, TEXT_DARK, [(cx - 6, cy - 9), (cx - 6, cy + 9), (cx + 8, cy)])
        else:
            pygame.draw.rect(self.screen, TEXT_DARK, (cx - 8, cy - 8, 6, 16), border_radius=2)
            pygame.draw.rect(self.screen, TEXT_DARK, (cx + 2, cy - 8, 6, 16), border_radius=2)

    def draw_credit(self):
        label = "GitHub · " + GITHUB_CREDIT
        tw = self.f_credit.size(label)[0]
        pill = pygame.Rect(10, self.H - 26, tw + 18, 18)
        ps = pygame.Surface(pill.size, pygame.SRCALPHA)
        pygame.draw.rect(ps, (255, 255, 255, 130), ps.get_rect(), border_radius=9)
        self.screen.blit(ps, pill.topleft)
        self.text(label, self.f_credit, CREDIT_COL, center=pill.center)

    def draw_dashed_line(self, x, y0, y1):
        y = y0
        while y < y1:
            pygame.draw.line(self.screen, (90, 85, 70), (x, y), (x, min(y + 7, y1)), 2)
            y += 15

    def draw_star(self, x, y, r, rot, col):
        pts = []
        for i in range(8):
            ang = rot + i * math.pi / 4
            rad = r if i % 2 == 0 else r * 0.42
            pts.append((x + math.cos(ang) * rad, y + math.sin(ang) * rad))
        pygame.draw.polygon(self.screen, col, pts)

    # ---------- overlays / cards ----------
    def overlay_alpha(self):
        return min(1.0, (pygame.time.get_ticks() - self.state_at) / 220.0)

    def dim(self):
        a = int(120 * self.overlay_alpha())
        ov = pygame.Surface((self.W, self.H), pygame.SRCALPHA)
        ov.fill((60, 48, 28, a))
        self.screen.blit(ov, (0, 0))

    def card(self, h):
        rect = pygame.Rect(0, 0, min(self.W - 44, 380), h)
        rect.center = (self.W / 2, self.H / 2)
        shadow_rect(self.screen, rect, radius=24, alpha=60, grow=8, yoff=8)
        pygame.draw.rect(self.screen, CARD, rect, border_radius=24)
        pygame.draw.rect(self.screen, (228, 218, 192), rect, 1, border_radius=24)
        return rect

    def button(self, name, rect, label, primary=True):
        self.btns[name] = rect
        hov = rect.collidepoint(self.mouse)
        if primary:
            shadow_rect(self.screen, rect, radius=24, alpha=50, grow=3, yoff=3)
            col = BTN_DARK_HOV if hov else BTN_DARK
            pygame.draw.rect(self.screen, col, rect, border_radius=24)
            self.text(label, self.f_btn, (255, 255, 255), center=rect.center)
        else:
            pygame.draw.rect(self.screen, (255, 255, 255), rect, border_radius=24)
            pygame.draw.rect(self.screen, (200, 190, 165), rect, 2, border_radius=24)
            self.text(label, self.f_btn, (90, 84, 70), center=rect.center)

    def draw_menu(self):
        self.dim()
        card = self.card(360)
        cx = card.centerx
        y = card.top + 44
        if self.sleeper_img is not None:
            face = self.circle_face(self.sleeper_img, 34)
            self.screen.blit(face, face.get_rect(center=(cx, y)))
            pygame.draw.circle(self.screen, GOLD, (cx, y), 35, 3)
        y += 62
        self.text("Bed Bounce", self.f_title, TEXT_DARK, center=(cx, y))
        y += 40
        for ln in ["Stick men fall from the sky.",
                   "Drag the bed to catch them.",
                   "Every catch = a bounce + 1 point.",
                   "Miss one and it's SPLAT!"]:
            self.text(ln, self.f_body, TEXT_MID, center=(cx, y))
            y += 23
        y += 12
        self.button("start", pygame.Rect(cx - 95, y, 190, 50), "Start Game")
        y += 66
        self.text("Best: %d" % self.best, self.f_body_b, GOLD_DARK, center=(cx, y))

    def draw_pause(self):
        self.dim()
        card = self.card(250)
        cx = card.centerx
        y = card.top + 48
        self.text("Paused", self.f_title, TEXT_DARK, center=(cx, y))
        y += 52
        self.button("resume", pygame.Rect(cx - 95, y, 190, 50), "Resume")
        y += 62
        self.button("restart", pygame.Rect(cx - 95, y, 190, 50), "Restart", primary=False)

    def draw_over(self):
        self.dim()
        card = self.card(330)
        cx = card.centerx
        y = card.top + 42
        self.text("Game Over", self.f_title, TEXT_DARK, center=(cx, y))
        y += 58
        self.text(str(self.score), self.f_big, TEXT_DARK, center=(cx, y))
        y += 52
        if self.new_best:
            label = "★  NEW BEST!  ★"
            tw = self.f_body_b.size(label)[0]
            pill = pygame.Rect(cx - tw / 2 - 14, y - 13, tw + 28, 26)
            pygame.draw.rect(self.screen, GOLD, pill, border_radius=13)
            self.text(label, self.f_body_b, (60, 42, 0), center=pill.center)
        else:
            self.text("BEST  %d" % self.best, self.f_best, TEXT_SOFT, center=(cx, y))
        y += 38
        msg = self.over_msg
        self.text(msg, self.f_body, TEXT_MID, center=(cx, y))
        y += 34
        self.button("again", pygame.Rect(cx - 95, y, 190, 50), "Play Again")

    # ---------- game flow ----------
    def set_score(self, v):
        self.score = v
        if v > self.best:
            self.best = v
            self._save_best()
            if self.state == "playing" and v > 1:
                self.new_best = True

    def spawn_faller(self):
        margin = 50
        self.faller = {
            "x": margin + random.random() * (self.W - margin * 2),
            "y": -50.0, "vy": 0.0, "vx": (random.random() - 0.5) * 0.6,
            "rot": 0.0, "vr": (random.random() - 0.5) * 0.02,
            "phase": random.random() * math.pi * 2,
            "img": random.choice(self.faller_imgs) if self.faller_imgs else None,
            "state": "falling", "r": 24,
        }

    def start_game(self):
        self.score = 0
        self.particles, self.flyers = [], []
        self.splat = None
        self.shake, self.flash_red = 0.0, 0.0
        self.new_best = False
        self.bed_x = self.bed_target = self.W / 2
        self.squash = 0.0
        self.spawn_faller()
        self.set_state("playing")
        self.hint_until = pygame.time.get_ticks() + 2600

    def bounce_off(self):
        f = self.faller
        f["state"] = "bounced"
        f["vy"] = -(11 + random.random() * 3 + min(self.score * 0.12, 3))
        f["vx"] = (1 if f["x"] >= self.bed_x else -1) * (1.6 + random.random() * 1.8)
        f["vr"] = (random.random() - 0.5) * 0.25
        self.flyers.append(f)
        self.faller = None
        self.squash = 1.0
        if self.snd_bounce:
            self.play(random.choice(self.snd_bounce))
        self.set_score(self.score + 1)
        for _ in range(12):
            self.particles.append({
                "x": f["x"], "y": self.bed_top - 4,
                "vx": (random.random() - 0.5) * 4, "vy": -random.random() * 3.4 - 0.6,
                "life": 1.0, "s": random.random() * 4 + 3,
                "rot": random.random() * math.pi, "vr": (random.random() - 0.5) * 0.3,
            })
        self.after(420 + random.random() * 380,
                   lambda: self.spawn_faller() if self.state == "playing" else None)

    def game_over(self):
        self.set_state("over")
        self.over_at = pygame.time.get_ticks()
        self.play(self.snd_splat)
        self.after(260, lambda: self.play(self.snd_over))
        self.over_msg = random.choice(OVER_MSGS)

    # ---------- update ----------
    def update(self, dt):
        now = pygame.time.get_ticks()
        due = [t for t in self.timers if now >= t[0]]
        self.timers = [t for t in self.timers if now < t[0]]
        for _, fn in due:
            fn()
        if self.state == "paused":
            return
        self.frame += 1
        self.bed_x += (self.bed_target - self.bed_x) * min(1, 0.42 * dt)
        if self.squash > 0:
            self.squash = max(0.0, self.squash - 0.09 * dt)
        if self.flash_red > 0:
            self.flash_red = max(0.0, self.flash_red - 0.03 * dt)
        if self.shake > 0:
            self.shake *= 0.86 ** dt
            if self.shake < 0.3:
                self.shake = 0.0

        f = self.faller
        if f and self.state == "playing" and f["state"] == "falling":
            grav = 0.34 + min(self.score * 0.012, 0.22)
            f["vy"] += grav * dt
            f["y"] += f["vy"] * dt
            f["x"] += f["vx"] * dt + math.sin(self.frame / 26 + f["phase"]) * 0.35 * dt
            f["rot"] = math.sin(self.frame / 20 + f["phase"]) * 0.14
            if f["x"] < 30:
                f["x"], f["vx"] = 30, abs(f["vx"])
            if f["x"] > self.W - 30:
                f["x"], f["vx"] = self.W - 30, -abs(f["vx"])
            feet_y = f["y"] + f["r"] * 0.85 + 26 + 24
            over_bed = (self.bed_x - self.bed_w / 2 + 14) < f["x"] < (self.bed_x + self.bed_w / 2 - 6)
            if f["vy"] > 0 and self.bed_top + 4 <= feet_y <= self.bed_top + 34 and over_bed:
                f["y"] -= feet_y - (self.bed_top + 4)
                self.bounce_off()
            elif feet_y >= self.floor_y + 8:
                self.splat = {"x": f["x"]}
                self.shake, self.flash_red = 13, 1.0
                self.faller = None
                self.game_over()

        for fl in list(self.flyers):
            fl["vy"] += 0.3 * dt
            fl["y"] += fl["vy"] * dt
            fl["x"] += fl["vx"] * dt
            fl["rot"] += fl["vr"] * dt
            if fl["y"] < -90 or fl["x"] < -70 or fl["x"] > self.W + 70:
                self.flyers.remove(fl)

        for p in list(self.particles):
            p["x"] += p["vx"] * dt
            p["y"] += p["vy"] * dt
            p["vy"] += 0.12 * dt
            p["rot"] += p["vr"] * dt
            p["life"] -= 0.03 * dt
            if p["life"] <= 0:
                self.particles.remove(p)

    # ---------- render ----------
    def render(self):
        s = self.screen
        self.btns = {}
        self.draw_background()
        ox = oy = 0
        if self.shake > 0:
            ox = (random.random() - 0.5) * self.shake
            oy = (random.random() - 0.5) * self.shake

        if self.splat:
            pygame.draw.ellipse(s, (40, 40, 40), (self.splat["x"] - 30 + ox, self.floor_y + 9 + oy, 60, 14))
            self.draw_star(self.splat["x"] - 22 + ox, self.floor_y + 12 + oy, 6, 0.4, (90, 84, 70))
            self.draw_star(self.splat["x"] + 24 + ox, self.floor_y + 14 + oy, 5, 1.1, (90, 84, 70))

        real_x = self.bed_x
        self.bed_x += ox
        self.draw_bed()
        self.bed_x = real_x

        if self.faller and self.faller["state"] == "falling" and self.state == "playing":
            f = self.faller
            self.draw_dashed_line(f["x"] + ox, f["y"] + f["r"] + 52 + oy, self.bed_top + oy)
        if self.faller:
            f = dict(self.faller)
            f["x"] += ox
            f["y"] += oy
            self.draw_stick(f)
        for fl in self.flyers:
            f = dict(fl)
            f["x"] += ox
            f["y"] += oy
            self.draw_stick(f)

        for p in self.particles:
            a = max(0.0, min(1.0, p["life"]))
            col = tuple(int(c * a + SKY_BOT[i] * (1 - a)) for i, c in enumerate(GOLD))
            self.draw_star(p["x"] + ox, p["y"] + oy, p["s"], p["rot"], col)

        if self.state == "playing":
            self.draw_quote()
        self.draw_hud()
        self.draw_corner_buttons()
        self.draw_credit()

        if self.state == "playing" and pygame.time.get_ticks() < self.hint_until:
            h = self.f_body.render("←  drag the bed to catch  →", True, TEXT_SOFT)
            h.set_alpha(200)
            s.blit(h, h.get_rect(center=(self.W / 2, self.floor_y - 14)))

        if self.state == "menu":
            self.draw_menu()
        elif self.state == "paused":
            self.draw_pause()
        elif self.state == "over" and pygame.time.get_ticks() - self.over_at > 650:
            self.draw_over()

        pygame.display.flip()

    # ---------- input / main loop ----------
    def click(self, pos):
        b = self.btns
        if self.state == "menu" and "start" in b and b["start"].collidepoint(pos):
            self.start_game()
            return
        if self.state == "paused":
            if "resume" in b and b["resume"].collidepoint(pos):
                self.set_state("playing")
                return
            if "restart" in b and b["restart"].collidepoint(pos):
                self.start_game()
                return
        if (self.state == "over" and pygame.time.get_ticks() - self.over_at > 650
                and "again" in b and b["again"].collidepoint(pos)):
            self.start_game()
            return
        if "sound" in b and b["sound"].collidepoint(pos):
            self.sound_on = not self.sound_on
            return
        if "pause" in b and b["pause"].collidepoint(pos) and self.state in ("playing", "paused"):
            self.set_state("paused" if self.state == "playing" else "playing")
            return
        if self.state == "playing":
            self.dragging = True
            self.drag_off = self.bed_target - pos[0]

    def run(self):
        running = True
        while running:
            ms = self.clock.tick(60)
            dt = min(ms / 16.7 or 1, 3)
            self.mouse = pygame.mouse.get_pos()
            for e in pygame.event.get():
                if e.type == pygame.QUIT:
                    running = False
                elif e.type == pygame.VIDEORESIZE:
                    self.W, self.H = e.w, e.h
                    self.screen = pygame.display.set_mode((self.W, self.H), pygame.RESIZABLE)
                    self.layout()
                elif e.type == pygame.DROPFILE:
                    try:
                        self.custom_face = pygame.image.load(e.file).convert_alpha()
                        self._face_cache.clear()
                    except Exception:
                        pass
                elif e.type == pygame.MOUSEBUTTONDOWN and e.button == 1:
                    self.click(e.pos)
                elif e.type == pygame.MOUSEBUTTONUP and e.button == 1:
                    self.dragging = False
                elif e.type == pygame.MOUSEMOTION and self.dragging and self.state == "playing":
                    nx = e.pos[0] + self.drag_off
                    self.bed_target = max(self.bed_w / 2 - 8, min(self.W - self.bed_w / 2 + 8, nx))
                elif e.type == pygame.KEYDOWN:
                    if e.key == pygame.K_m:
                        self.sound_on = not self.sound_on
                    elif e.key in (pygame.K_RETURN, pygame.K_KP_ENTER):
                        if self.state in ("menu", "over"):
                            self.start_game()
                    elif e.key in (pygame.K_SPACE, pygame.K_ESCAPE):
                        if self.state == "playing":
                            self.set_state("paused")
                        elif self.state == "paused":
                            self.set_state("playing")
                    elif self.state == "playing" and e.key == pygame.K_LEFT:
                        self.bed_target = max(self.bed_w / 2, self.bed_target - 42)
                    elif self.state == "playing" and e.key == pygame.K_RIGHT:
                        self.bed_target = min(self.W - self.bed_w / 2, self.bed_target + 42)
            self.update(dt)
            self.render()
        pygame.quit()
        sys.exit(0)


if __name__ == "__main__":
    BedBounce().run()
